select chapter_id,count(*) criteria_count,sum(max_score) max_score,count(*) filter(where row_status='needs_revision') awaiting_text_review from public.legal_import_rows where batch_id=(select id from public.legal_import_batches where batch_version='QD2429-2017-v1') group by chapter_id order by chapter_id;
select count(*) rows_total,count(distinct chapter_id) chapters,sum(max_score) max_score,count(*) filter(where legal_text='Chờ quản trị viên xác minh theo phụ lục Quyết định 2429/QĐ-BYT.') legal_text_pending from public.legal_import_rows where batch_id=(select id from public.legal_import_batches where batch_version='QD2429-2017-v1');
